import{_ as t,o as n,c as a,a0 as i}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"✨ WealthFam Features","description":"","frontmatter":{},"headers":[],"relativePath":"user/features.md","filePath":"user/features.md"}'),o={name:"user/features.md"};function r(s,e,l,c,d,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="✨-wealthfam-features" tabindex="-1">✨ WealthFam Features <a class="header-anchor" href="#✨-wealthfam-features" aria-label="Permalink to &quot;✨ WealthFam Features&quot;">​</a></h1><p>A comprehensive overview of what you can achieve with WealthFam.</p><h2 id="📊-holistic-dashboard" tabindex="-1">📊 Holistic Dashboard <a class="header-anchor" href="#📊-holistic-dashboard" aria-label="Permalink to &quot;📊 Holistic Dashboard&quot;">​</a></h2><ul><li><strong>Real-time Balance Sheet</strong>: Instantly view Net Worth, Liquidity, and Debt.</li><li><strong>Spending Velocity</strong>: Sparklines and category breakdowns.</li></ul><h2 id="📈-mutual-funds-tracking" tabindex="-1">📈 Mutual Funds Tracking <a class="header-anchor" href="#📈-mutual-funds-tracking" aria-label="Permalink to &quot;📈 Mutual Funds Tracking&quot;">​</a></h2><ul><li><strong>XIRR &amp; Performance</strong>: Automated tracking.</li><li><strong>Unified Portfolio</strong>: Manage multiple folios.</li></ul><h2 id="🧠-ai-intelligence" tabindex="-1">🧠 AI Intelligence <a class="header-anchor" href="#🧠-ai-intelligence" aria-label="Permalink to &quot;🧠 AI Intelligence&quot;">​</a></h2><ul><li><strong>Smart Categorization</strong>: Automated classification.</li><li><strong>Deep Insights</strong>: Gemini-powered analytics.</li></ul><h2 id="🕒-subscription-management" tabindex="-1">🕒 Subscription Management <a class="header-anchor" href="#🕒-subscription-management" aria-label="Permalink to &quot;🕒 Subscription Management&quot;">​</a></h2><ul><li><strong>Recurring Transactions</strong>: Factor billing into liquidity.</li></ul><h2 id="🏦-specialized-financial-instruments" tabindex="-1">🏦 Specialized Financial Instruments <a class="header-anchor" href="#🏦-specialized-financial-instruments" aria-label="Permalink to &quot;🏦 Specialized Financial Instruments&quot;">​</a></h2><ul><li><strong>Fixed &amp; Recurring Deposits</strong>: Track deposits with automated compounding interest simulation, tenure timelines, and maturity projections.</li><li><strong>Provident Funds (EPF / PPF / NPS)</strong>: Tripartite EPF split (Employee, Employer, Pension), annual statutory interest estimation, and post-tax statutory deposit tracking (₹1.5L annual ceiling).</li><li><strong>Credit Cards</strong>: Track statement cycles (<code>current_unbilled</code>, <code>last_statement</code>), utilization health, bill due dates, and minimum payments due.</li><li><strong>Loans &amp; EMIs</strong>: Manage lenders, track loan account numbers, and monitor EMI debits.</li></ul><h2 id="🔄-cross-account-transfers-pairing" tabindex="-1">🔄 Cross-Account Transfers &amp; Pairing <a class="header-anchor" href="#🔄-cross-account-transfers-pairing" aria-label="Permalink to &quot;🔄 Cross-Account Transfers &amp; Pairing&quot;">​</a></h2><ul><li><strong>Automated Match Detection</strong>: Smart heuristic engine detects funds moving between your own accounts (e.g. Bank to Card bill payment or savings transfers).</li><li><strong>Zero Expense Inflation</strong>: Paired transfers are automatically excluded from spending analytics, keeping cash flow reports accurate.</li><li><strong>1-Click Counterpart Leg Generation</strong>: Auto-generate missing receiving credits directly with adjustable amounts for cashback or payment discounts.</li></ul><h2 id="📂-document-vault-attachments" tabindex="-1">📂 Document Vault &amp; Attachments <a class="header-anchor" href="#📂-document-vault-attachments" aria-label="Permalink to &quot;📂 Document Vault &amp; Attachments&quot;">​</a></h2><ul><li><strong>Persistent <code>/data/vault</code> Storage &amp; Self-Healing</strong>: Documents persist across container upgrades in <code>/data/vault</code> with automatic startup/runtime path self-healing and surviving earlier-version fallback resolution.</li><li><strong>Hierarchical Storage</strong>: Organize tax forms, receipts, statements, and investment documents in nested folders.</li><li><strong>Transaction Linking &amp; Lazy Previews</strong>: Attach receipts and invoices directly to transactions with in-app PDF and image previews, on-demand auto-unlocking of legacy encrypted statement PDFs, and lazy thumbnail generation without 404 console spam on locked PDFs.</li></ul><h2 id="📱-mobile-app-android" tabindex="-1">📱 Mobile App (Android) <a class="header-anchor" href="#📱-mobile-app-android" aria-label="Permalink to &quot;📱 Mobile App (Android)&quot;">​</a></h2><ul><li><strong>Real-time Ingestion</strong>: Automated SMS financial alert capture with high-accuracy GPS tagging.</li><li><strong>Mobile Transfers Hub</strong>: Approve detected transfers in bulk and create counterpart legs on the go.</li><li><strong>Dedicated Instrument Views</strong>: Instant mobile access to Deposits, Provident Funds, and Credit Cards.</li><li><strong>Active Expense Group Assignment</strong>: Group assignment picker cleanly filters out archived groups while preserving historical assignments.</li><li><strong>Living vs Total Spend Alignment</strong>: Ledger spend headers explicitly reconcile operational living spending against investments and internal transfers with clear tooltip breakdowns.</li></ul><h2 id="🏦-bulk-statement-reconciliation-management" tabindex="-1">🏦 Bulk Statement Reconciliation &amp; Management <a class="header-anchor" href="#🏦-bulk-statement-reconciliation-management" aria-label="Permalink to &quot;🏦 Bulk Statement Reconciliation &amp; Management&quot;">​</a></h2><ul><li><strong>Attended Statements Hidden by Default</strong>: Attended statements are hidden by default across Web and Mobile to keep review queues clean and focused on action items. A 1-click <strong>Show Attended / Showing Attended</strong> toggle reveals both attended and unattended statements whenever audit is needed, with real-time selection auto-advance upon attending.</li><li><strong>Statement-Level Full CRUD</strong>: Upload or email-sync PDF statements, filter by status (<code>All</code>, <code>Parsed</code>, <code>Pending</code>, <code>Failed</code>) and filename, edit filename (synced with Vault), statement type, and linked account, and delete single or multiple statements with optional Vault PDF removal.</li><li><strong>Statement Ignore Rules</strong>: Block recurring promotional/non-statement email PDFs by sender, email subject, or filename keyword directly from the <strong>Statements</strong> view (via the <strong>Ignored Rules</strong> manager or single-statement 🚫 Ignore modal) as well as <strong>Settings → Ingestions</strong>, with bulk cleanup of existing matching <code>PENDING</code>/<code>FAILED</code> items while keeping <code>PARSED</code> history safe.</li><li><strong>Smart PDF &amp; CDSL eCAS Ingestion</strong>: Specialized extraction for bank statements, credit cards, and Consolidated Account Statements (CAMS, KFintech, CDSL <code>eCAS@cdslstatement.com</code>, NSDL), SHA-256 version deduplication preventing duplicate Vault versions on retries, and partial-unlock reprocess continuity when decryption succeeds ahead of parsing.</li><li><strong>Automated Rule Persistence</strong>: Generate classification rules directly from ingestion flows with PostgreSQL-safe JSON keyword queries.</li><li><strong>Bulk Triage &amp; Normalized Categories</strong>: Confirm hundreds of transactions in seconds with searchable category selection (<code>:teleport=&quot;true&quot;</code> to prevent container clipping) and leaf-category normalization.</li><li><strong>Pending Triage Auto-Promotion</strong>: Reconciling statement transactions automatically resolves matching pending triage items into official ledger records.</li><li><strong>Category Rules Review Prioritization</strong>: Rules matching pending triage items are automatically pinned to the top of the rules list with amber badges (<code>⚡ X in Review</code>) and quick-filter toggles.</li></ul><h2 id="⚡-global-attention-action-required-hub" tabindex="-1">⚡ Global Attention &amp; Action Required Hub <a class="header-anchor" href="#⚡-global-attention-action-required-hub" aria-label="Permalink to &quot;⚡ Global Attention &amp; Action Required Hub&quot;">​</a></h2><ul><li><strong>Unified Action Center</strong>: Top-bar unified Bell icon with pending badge count (<code>🔔 {N}</code>) on Web and dynamic &quot;Pending Actions&quot; row on Mobile aggregating all pending financial decisions into a single click-to-resolve queue.</li><li><strong>Statement Attendance Lifecycle</strong>: Explicitly mark parsed statements as &quot;Attended &amp; Closed&quot; or reopen them, with protective confirmation warnings when unreconciled transactions remain and auto-resetting upon reprocessing.</li><li><strong>Multi-Domain Intelligence</strong>: Automatically detects pending triage transactions, suggested cross-account transfers, overdue or approaching credit card bills, category budget breaches, loan EMI deadlines, recurring subscription patterns, account low-balance/overdraft states, and stale mutual fund CAS statements.</li><li><strong>Child Account Shielding</strong>: Automatic role-based security strictly hides household debts, loans, statements, and financial accounts from child members while preserving their personal triage queue.</li><li><strong>Sub-15ms Single-Pass Aggregation</strong>: High-performance conditional aggregation engine ensuring instant UI responsiveness without background polling load spikes.</li></ul>',22)])])}const h=t(o,[["render",r]]);export{m as __pageData,h as default};
